/// </summary>
[UPSPricingMetadataDiscovery][UPSPricingAttributeSourceDiscovery(UPSPricingAttributeSource::Product, UPSPricingAttributeSourceLevel::Line)]
internal class UPSPricingAttributePdsCatchWeightItemPdsCWMin extends UPSPricingAttributePdsCatchWeightItem implements UPSIPricingAttribute
{
}

Method.Source:
public str getName()
{
    return fieldPName(PdsCatchWeightItem, PdsCWMin);
}

public Set getAllowedValues()
{
    var                ret = new Set(Types::Real);
    PdsCatchWeightItem pdsCatchWeightItem;

    while select pdsCatchWeightItem
        group by PdsCWMin
    {
        if (! ret.in(pdsCatchWeightItem.PdsCWMin))
        {
            ret.add(pdsCatchWeightItem.PdsCWMin);
        }
    }

    return ret;
}

protected void setQueryBuildDatasourceRange(QueryBuildDataSource _qbds, anytype _value)
{
    QueryBuildRange qbr;

    qbr = _qbds.addRange(fieldNum(PdsCatchWeightItem, PdsCWMin));
    qbr.value(queryValue(_value));
}
